import { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from './BackButton';

interface Post {
  userId: number;
  id: number;
  title: string;
  body: string;
}

interface Comment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

interface PageProps {
  params: Promise<{ id: string }>;
}

// Generate static params for the first 10 posts
export async function generateStaticParams() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then(res => res.json());

  return posts.slice(0, 10).map((post: Post) => ({
    id: post.id.toString(),
  }));
}

// Generate metadata dynamically
export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params;

  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 }, // 5 minutes
    }).then(res => {
      if (!res.ok) throw new Error('Post not found');
      return res.json();
    });

    return {
      title: post.title,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    };
  } catch {
    return {
      title: 'Post Not Found',
    };
  }
}

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 }, // 5 minutes
      }).then(res => {
        if (!res.ok) throw new Error('Post not found');
        return res.json();
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then(res => res.json()),
    ]);

    return { post, comments };
  } catch {
    return null;
  }
}

export default async function BlogPost({ params }: PageProps) {
  const { id } = await params;
  const data = await getPostData(id);

  if (!data) {
    notFound();
  }

  const { post, comments } = data;

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map(comment => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

